head.script:
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

xf:group.script:
				/**
                * //property handling
                * $w.log("id:" + options.id);
                * $w.log("class:" + options.class);
                * $w.log("style:" + options.style);
                *
                * //event trigger
                */

                /**
                 * UDC 스크립트 작성
                 * 
                 * 설명 : 메일주소 입력 컴포넌트.
                 * 기능 : 메일주소를 입력.
                 */
				var UDC_ID = this.id;
				var UDC_ref = udc_obj.options.ref || "";
				var addressBox;
				var mailTypeBox;
				var sbxComp;
				var dataListComp;

                /**
                 * UDC컴포넌트 기본 설정 [내부 컴포넌트 및 동적이벤트 설정.]
                 *
                 * @date 2015. 04. 24.
                 * @param 
                 * @return
                 */
				scwin.init = function() {
					addressBox = WebSquare.wUnit.getObjById(UDC_ID + "_ibx_address");
					addressBox.bind("onviewchange", function(info) { scwin.validate(this, 1); });
					mailTypeBox = WebSquare.wUnit.getObjById(UDC_ID + "_ibx_mailType");
					mailTypeBox.bind("onviewchange", function(info) { scwin.validate(this, 2); });
					sbxComp = WebSquare.wUnit.getObjById(UDC_ID + "_sbx_type");
					sbxComp.bind("onviewchange", function(info) { scwin.mailTypeCallBack(info.newValue); });
					scwin.createCollection();

					if (typeof udc_obj.options.refMail !== "undefined" && udc_obj.options.refMail !== "") {
						addressBox.setRef(UDC_ref+"."+udc_obj.options.refMail);
					}
					if (typeof udc_obj.options.refMailType !== "undefined" && udc_obj.options.refMailType !== "") {
						mailTypeBox.setRef(UDC_ref+"."+udc_obj.options.refMailType);
					}
					if (typeof udc_obj.options.readOnly !== "undefined" && udc_obj.options.readOnly !== "") {
						var flag = WebSquare.util.getBoolean(udc_obj.options.readOnly);
						addressBox.setReadOnly(flag);
						mailTypeBox.setReadOnly(flag);
						sbxComp.setReadOnly(flag);
					}
					if (typeof udc_obj.options.disabled !== "undefined" && udc_obj.options.disabled !== "") {
						var flag = WebSquare.util.getBoolean(udc_obj.options.disabled);
						addressBox.setDisabled(flag);
						mailTypeBox.setDisabled(flag);
						sbxComp.setDisabled(flag);
					}
					if (typeof udc_obj.options.requisite !== "undefined" && udc_obj.options.requisite !== "" && udc_obj.options.requisite) {
						addressBox.addClass("pt");
						mailTypeBox.addClass("pt");
						sbxComp.addClass("pt");
					}
				}

				scwin.init();


                /**
                 * 내부 컴포넌트함수 [동적 dataCollection 생성 함수.]
                 *
                 * @date 2015. 04. 24.
                 * @param 
                 * @return
                 */  
                scwin.createCollection = function() {
                    create({
                        "id": UDC_ID +"_dlt_mailType", 
                        "type" : "dataList", 
                        "option" : {"baseNode" : "vector", "repeatNode" : "item"}, 
                        "columnInfo" : [{"id" : "label"}, {"id" : "value"}]
                    });
                    dataListComp = WebSquare.wUnit.getObjById(UDC_ID + "_dlt_mailType");
                    dataListComp.setJSON([{"label":"naver.com", "value":"naver.com"},{"label":"daum.net", "value":"daum.net"},
                        {"label":"hotmail.com", "value":"hotmail.com"},{"label":"nate.com", "value":"nate.com"},{"label":"yahoo.co.kr", "value":"yahoo.co.kr"},
                        {"label":"empas.com", "value":"empas.com"},{"label":"dreamwiz.com", "value":"dreamwiz.com"},{"label":"gamil.com", "value":"gamil.com"},
                        {"label":"lycos.co.kr", "value":"lycos.co.kr"},{"label":"korea.com", "value":"korea.com"}
                        ]);
                    sbxComp.setNodeSet("data:"+dataListComp.id,"label","value");
                };

                /**
                 * 내부 컴포넌트함수 [메일주소타입 onchangeEvent 콜백함수.]
                 *
                 * @date 2015. 04. 24.
                 * @param 
                 * @return
                 */  
                scwin.mailTypeCallBack = function(value) {
                    if (value != "") {
                        mailTypeBox.setReadOnly(true);
                    } else {
                        mailTypeBox.setReadOnly(false);
                    }
                    mailTypeBox.setValue(value);
                };

                /**
                 * 내부 컴포넌트함수 [메일주소 validate함수.]
                 *
                 * @date 2015. 04. 24.
                 * @param {Object} comp : 입력 input 컴포넌트.
                 * @param {type} type : 메일주소, 메일타입 확인.
                 * @return
                 */  
                scwin.validate = function(comp, type) {
                    var value = comp.getValue();
                    var reg_mailId = /^[-A-Za-z0-9_]+[-A-Za-z0-9_.]$/;
                    var reg_mailType =  /^[-A-Za-z0-9_]+[-A-Za-z0-9_.]*[.]{1}[A-Za-z]{2,5}$/;
                    if (type == 1) {
                        if (value.length == "") {
                            alert("메일을 입력해주세요.");
                            comp.focus();
                        } else if (value.search(reg_mailId) < 0 ) {
                            alert("메일 형식이 잘못되었습니다.");
                            comp.focus();
                        }
                    } else if (type == 2) {
                        if (value.length == "") {
                            alert("메일타입을 입력해주세요.");
                            comp.focus();
                        } else if (value.search(reg_mailType) < 0 ) {
                            alert("메일 형식이 잘못되었습니다.");
                            comp.focus();
                        }
                    }
                };

                /**
                 * UDC 컴포넌트함수 [메일주소 설정함수.]
                 *
                 * @date 2015. 04. 24.
                 * @param {String} value : 메일주소값.
                 * @return {Boolean} 메일주소 설정 성공 유무.
                 */
				this.setMail= function(value){
					var split = value.split("@");
					var isSuccess;
					var reg_mailId = /^[-A-Za-z0-9_]+[-A-Za-z0-9_.]$/;
                    var reg_mailType =  /^[-A-Za-z0-9_]+[-A-Za-z0-9_.]*[.]{1}[A-Za-z]{2,5}$/;

					if (split.length > 2) {
						isSuccess =false;
					} else {
						if(split.length > 1 && split[0].search(reg_mailId) > -1 && split[1].search(reg_mailType) > -1) {
							addressBox.setValue(split[0]);
							mailTypeBox.setValue(split[1]);
							sbxComp.setValue("");
							isSuccess = true;
						} else if (split.length > 0 && split[0].search(reg_mailId) > -1) {
							addressBox.setValue(split[0]);
							isSuccess = true;
						} else {
							isSuccess = false;
						}
					}
					return isSuccess;
				};

                /**
                 * UDC 컴포넌트함수 [메일주소 반환함수.]
                 *
                 * @date 2015. 04. 24.
                 * @param
                 * @return {String} 입력된 메일주소 값.
                 */
				this.getMail= function(){
					var mail = false;
					if (addressBox.getValue() != "" &&  ibx_mailType.getValue() != "") {
						mail = addressBox.getValue() + "@" + ibx_mailType.getValue();
					}
					return mail;
				};

                /**
                 * UDC 컴포넌트함수 [메일주소타입 추가 설정.]
                 *
                 * @date 2015. 04. 24.
                 * @param {Object} typeOptions : 메일주소타입 설정 options.
                 *   typeOptions.label : 메일주소 타입 (ex. naver.com)
                 *   typeOptions.value : 메일주소타입에 따른 value 값.
                 * @param {Boolean} append : 메일주소타입 append 여부설정 | default : true.
                 * @return {Booelean} 설정 성공 여부.
                 */
				this.setMailTypeJSON= function(typeOptions, append){
					var isSetting = false;
					var append = append || true;
					if (jsonLib.isJSON(typeOptions)) {
						dataListComp.setJSON(typeOptions, append);
        				sbxComp.setNodeSet("data:"+dataListComp.id,"label","value");
						isSetting = true;
					}
					return isSetting;
				};


				/**
                 * UDC 컴포넌트함수 [메일주소 UDC 컴포넌트에 disabled속성을 정의합니다.]
                 *
                 * @date 2015. 04. 24.
                 * @param {Boolean} flag : disabled 정의 여부.
                 * @return {Boolean} 메일주소 UDC 컴포넌트 disabled 값.
                 */
				this.setDisabled = function( flag ){
					var flag = WebSquare.util.getBoolean( flag );
					udc_obj.options.disabled = flag;
					addressBox.setDisabled(flag);
					mailTypeBox.setDisabled(flag);
					sbxComp.setDisabled(flag);

					return flag;
				};

				/**
                 * UDC 컴포넌트함수 [메일주소 UDC 컴포넌트에 disabled속성 값을 반환합니다.]
                 *
                 * @date 2015. 04. 24.
                 * @param 
                 * @return {Boolean} 메일주소 UDC 컴포넌트 disabled 값.
                 */
				this.getDisabled = function(){
					var flag = WebSquare.util.getBoolean( udc_obj.options.disabled );
					return flag;
				};

				 /**
                 * UDC 컴포넌트함수 [메일주소 UDC 컴포넌트에 readOnly속성을 정의합니다.]
                 *
                 * @date 2015. 04. 24.
                 * @param {Boolean} flag : readOnly 정의 여부.
                 * @return {Boolean} 메일주소 UDC 컴포넌트 readOnly 값.
                 */
				this.setReadOnly = function(flag){
					var flag = WebSquare.util.getBoolean( flag );
					udc_obj.options.readOnly = flag;
					addressBox.setReadOnly(flag);
					mailTypeBox.setReadOnly(flag);
					sbxComp.setReadOnly(flag);

					return flag;
				};

				/**
                 * UDC 컴포넌트함수 [메일주소 UDC 컴포넌트에 readOnly속성 값을 반환합니다.]
                 *
                 * @date 2015. 04. 24.
                 * @param 
                 * @return {Boolean} 메일주소 UDC 컴포넌트 readOnly 값.
                 */
				this.getReadOnly = function(){
					var flag = WebSquare.util.getBoolean( udc_obj.options.readOnly );
					return flag;
				};

				/**
                 * UDC 컴포넌트함수 [메일주소 UDC 컴포넌트의 데이터를 초기화합니다.]
                 *
                 * @date 2015. 06. 22.
                 * @param 
                 * @return 
                 */
				this.reset = function(){
					addressBox.setValue("");
					mailTypeBox.setValue("");
					mailTypeBox.setReadOnly(false);
					sbxComp.setValue("");
				};
